import React, { useState, useEffect, useRef } from 'react';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in genom näsan', speed:0.04,  distort:0.15 },
  { name:'Håll',      seconds:7, label:'Håll andan stilla',    speed:0.005, distort:0.06 },
  { name:'Andas ut',  seconds:8, label:'Sakta ut',             speed:0.02,  distort:1.6  },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{
      c--; setCount(c);
      if (c<=0){ clearInterval(timer.current); const np=(pi+1)%PHASES.length; setTimeout(()=>runPhase(np,np===0?ci+1:ci),350); }
    },1000);
  };
  const start = () => { setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current),[]);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 40%, rgba(40,60,50,0.15) 0%, transparent 55%)', pointerEvents:'none' }} />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={220} speed={0.65} distort={0.15} />
        </div>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:10 }}>{TOTAL} omgångar · komplett</div>
        <h2 style={{ fontSize:40, fontWeight:900, letterSpacing:'-0.05em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:10 }}>Färdig</h2>
        <p style={{ fontSize:14, color:'rgba(242,240,235,0.4)', marginBottom:36, fontWeight:300 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 22px', borderRadius:12, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', fontSize:11, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', boxShadow:'0 4px 20px rgba(0,0,0,0.4)' }}>Check-in →</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} className="liq" style={{ padding:'12px 22px', borderRadius:12, color:'rgba(242,240,235,0.55)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 50%, rgba(40,50,80,0.15) 0%, transparent 60%)', pointerEvents:'none' }} />

      {/* Phase indicators */}
      <div style={{ padding:'20px 20px 0', position:'relative', zIndex:1 }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:14 }}>4 – 7 – 8 teknik</div>
        <div style={{ display:'flex', gap:20 }}>
          {PHASES.map((p,i)=>(
            <div key={i} style={{ transition:'all .5s' }}>
              <div style={{ fontSize:22, fontWeight:900, letterSpacing:'-0.04em', color: running&&phase===i ? '#f2f0eb' : 'rgba(242,240,235,0.18)', transition:'color .5s' }}>{p.seconds}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.1em', textTransform:'uppercase', color: running&&phase===i ? 'rgba(242,240,235,0.5)' : 'rgba(242,240,235,0.15)', transition:'color .5s', marginTop:2 }}>{p.name}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Sphere — the breathing object */}
      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', position:'relative', zIndex:1 }}>
        <div style={{
          transition: running
            ? phase===0 ? `transform ${PHASES[0].seconds*.82}s cubic-bezier(0.25,0,0.1,1)`
            : phase===1 ? 'transform .6s ease'
            : `transform ${PHASES[2].seconds*.82}s cubic-bezier(0.9,0,0.75,1)`
            : 'transform 1.2s cubic-bezier(0.16,1,0.3,1)',
          transform: running ? (phase===0||phase===1 ? 'scale(1.22)' : 'scale(0.8)') : 'scale(1)',
          position:'relative',
        }}>
          <MeshSphere size={280} speed={running ? cur.speed : 0.28} distort={running ? cur.distort : 0.45} color='#f2f0eb' />
          {running && (
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.4)', marginBottom:4 }}>{cur.name}</div>
              <div style={{ fontSize:62, fontWeight:900, color:'rgba(242,240,235,0.88)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.28)', marginTop:6 }}>{cycle+1} / {TOTAL}</div>
            </div>
          )}
        </div>
      </div>

      {/* Bottom */}
      <div style={{ padding:'0 16px 16px', position:'relative', zIndex:1 }}>
        {running ? (
          <div className="liq" style={{ padding:'14px 18px', textAlign:'center', borderRadius:18 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(242,240,235,0.5)' }}>{cur.label}</p>
          </div>
        ) : (
          <div>
            <h1 style={{ fontSize:'clamp(32px,8vw,52px)', fontWeight:900, letterSpacing:'-0.055em', lineHeight:0.88, color:'#f2f0eb', textTransform:'uppercase', marginBottom:10 }}>
              ANDNING<br/><span style={{ color:'rgba(242,240,235,0.18)' }}>ÖVNING</span>
            </h1>
            <p style={{ fontSize:13, color:'rgba(242,240,235,0.4)', fontWeight:300, lineHeight:1.75, marginBottom:20, maxWidth:300 }}>
              Aktiverar det parasympatiska nervsystemet och reducerar stresshormoner på 4 minuter.
            </p>
            <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:14, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', fontSize:12, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.16em', textTransform:'uppercase', boxShadow:'0 4px 24px rgba(0,0,0,0.45)' }}>
              Starta →
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
